const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const message = data.message || {};

const phone = (data.key?.remoteJid || body.remoteJid || '').replace('@s.whatsapp.net', '').replace('@c.us', '');
const pushName = data.pushName || body.pushName || 'Cliente';
const messageId = data.key?.id || body.messageId || '';

// Detecta tipo de mensagem
const isAudio = !!(message.audioMessage || message.pttMessage);
const isImage = !!(message.imageMessage);
const isDocument = !!(message.documentMessage);
const isMedia = isImage || isDocument;

// Captura base64 e mimetype de imagem/documento
const mediaBase64 = (isImage || isDocument) ? (message.base64 || data.base64 || body.base64 || '') : '';
const mediaMimeType = message.imageMessage?.mimetype ||
                     message.documentMessage?.mimetype || 'image/jpeg';
const mediaCaption = message.imageMessage?.caption ||
                     message.documentMessage?.caption || '';
const mediaFileName = message.documentMessage?.fileName || '';

// Captura base64 de áudio
const audioBase64 = isAudio ? (message.base64 || data.base64 || body.base64 || message.audioMessage?.base64 || '') : '';
const audioUrl = message.audioMessage?.url || message.pttMessage?.url || '';

const text = message.conversation || message.extendedTextMessage?.text || body.text || '';

if (!phone || phone.includes('-')) {
  throw new Error('Mensagem ignorada: vazia ou de grupo');
}

return [{
  json: {
    phone,
    text,
    messageId,
    pushName,
    isAudio,
    isImage,
    isDocument,
    isMedia,
    audioUrl,
    audioBase64,
    mediaBase64,
    mediaMimeType,
    mediaCaption,
    mediaFileName
  }
}];

const whisperData = $input.first().json;
const dadosOriginais = $('Extrair Dados da Mensagem').item.json;
const textoTranscrito = whisperData?.text || whisperData?.transcription || '';
return [{
  json: {
    phone: dadosOriginais.phone,
    pushName: dadosOriginais.pushName,
    text: textoTranscrito,
    messageId: dadosOriginais.messageId,
    isAudio: true,
    isMedia: false
  }
}];

let dadosFinal;
try {
  dadosFinal = $('Unificar Transcrição').item.json;
  if (dadosFinal) return [{ json: dadosFinal }];
} catch (e) {}

const extrair = $('Extrair Dados da Mensagem').item.json;
let texto = extrair.text;
if (!texto && extrair.isMedia) {
  texto = extrair.mediaCaption
    ? `[Cliente enviou uma imagem/arquivo] ${extrair.mediaCaption}`
    : '[Cliente enviou uma imagem/arquivo]';
}
return [{ json: { ...extrair, text: texto || 'Olá' } }];

const extrair = $('Merge Texto+Audio').item.json;
let clienteData;
try {
  const novoResp = $('Cadastrar Novo Cliente').item.json;
  const arr = Array.isArray(novoResp) ? novoResp : [novoResp];
  if (arr.length > 0 && arr[0].id) clienteData = arr[0];
} catch (e) {}
if (!clienteData) {
  const existenteResp = $('Buscar Cliente').item.json;
  const arr = Array.isArray(existenteResp) ? existenteResp : [existenteResp];
  clienteData = arr.length > 0 ? arr[0] : {};
}
return [{
  json: {
    phone: extrair.phone,
    pushName: extrair.pushName,
    userMessage: extrair.text,
    isAudio: extrair.isAudio || false,
    isMedia: extrair.isMedia || false,
    clienteId: clienteData?.id,
    nomeCliente: clienteData?.nome || extrair.pushName,
    stage: clienteData?.stage || 'NOVO',
    visitaAgendada: clienteData?.visita_agendada || false,
    dataVisita: clienteData?.data_visita || ''
  }
}];

const cliente = $('Unificar Dados do Cliente').item.json;
const rawInput = $input.all();
let historico = [];
if (rawInput.length === 1 && Array.isArray(rawInput[0].json)) {
  historico = rawInput[0].json;
} else {
  historico = rawInput.map(i => i.json).filter(i => i && i.role);
}

const stage = cliente.stage;
const nomeCliente = cliente.nomeCliente || 'você';

const IMOVEL = {
  titulo: 'Apartamento Vila Madalena',
  endereco: 'Vila Madalena, São Paulo/SP',
  descricao: '2 quartos, sala ampla, varanda, 1 vaga de garagem. Próximo ao metrô e à vida cultural da Vila Madalena.'
};

const instrucaoAgendamento = `Quando o cliente confirmar um dia e horário para a visita (qualquer dia e horário são aceitos, não há restrição de agenda), responda confirmando a visita normalmente para o cliente E adicione ao final da sua resposta, em uma linha própria, a marcação: [AGENDAR: <dia e horário exatamente como o cliente combinou>]. Essa marcação é apenas para o sistema, o cliente não deve ver esse texto.`;

const prompts = {
  NOVO: `Você é a Bia, corretora virtual de imóveis, atendendo pelo WhatsApp 🏠

IMÓVEL EM DESTAQUE:
- ${IMOVEL.titulo}
- Endereço: ${IMOVEL.endereco}
- Características: ${IMOVEL.descricao}
- A foto do imóvel já foi enviada ao cliente antes desta mensagem.

PERSONALIDADE:
- Calorosa, simpática e objetiva
- Use o nome do cliente: ${nomeCliente}
- Use emojis com moderação

INSTRUÇÃO:
Dê as boas-vindas ao ${nomeCliente}, comente que o ${IMOVEL.titulo} (a foto que acabou de enviar) está disponível, destaque rapidamente os pontos fortes do imóvel, e tente marcar uma visita. Aceite qualquer dia e horário que o cliente sugerir, sem restrição.
${instrucaoAgendamento}

REGRAS:
- NUNCA diga que é uma IA, robô ou assistente virtual automatizado
- Responda apenas sobre o imóvel e o agendamento da visita
- Não invente informações que não foram passadas (preço, condições de pagamento) — se perguntarem, diga que o corretor responsável confirma os detalhes na visita`,

  ATENDIMENTO: `Você é a Bia, corretora virtual de imóveis, atendendo pelo WhatsApp 🏠

IMÓVEL EM DESTAQUE:
- ${IMOVEL.titulo}
- Endereço: ${IMOVEL.endereco}
- Características: ${IMOVEL.descricao}

PERSONALIDADE:
- Calorosa, simpática e objetiva
- Use o nome do cliente: ${nomeCliente}
- Use emojis com moderação

INSTRUÇÃO:
Continue a conversa, responda dúvidas sobre o imóvel com as informações acima, e sempre que possível tente marcar a visita. Aceite qualquer dia e horário que o cliente sugerir, sem restrição.
${instrucaoAgendamento}

REGRAS:
- NUNCA diga que é uma IA, robô ou assistente virtual automatizado
- Não invente preço ou condições de pagamento — diga que o corretor confirma na visita
- Se o cliente perguntar algo fora do assunto do imóvel, traga gentilmente a conversa de volta para o agendamento da visita`,

  VISITA_AGENDADA: `Você é a Bia, corretora virtual de imóveis, atendendo pelo WhatsApp 🏠

IMÓVEL EM DESTAQUE:
- ${IMOVEL.titulo}
- Endereço: ${IMOVEL.endereco}

SITUAÇÃO: O cliente ${nomeCliente} já tem uma visita agendada para: ${cliente.dataVisita || 'o horário combinado'}.

INSTRUÇÃO:
Confirme os detalhes se o cliente perguntar, tire dúvidas sobre o imóvel, e se o cliente quiser mudar o dia/horário, combine o novo horário (aceite qualquer dia/horário) e use novamente a marcação de agendamento.
${instrucaoAgendamento}

REGRAS:
- NUNCA diga que é uma IA, robô ou assistente virtual automatizado
- Não invente preço ou condições de pagamento`
};

const systemPrompt = prompts[stage] || prompts['NOVO'];

const historicoFormatado = historico.length > 0
  ? '\n\n=== HISTÓRICO DA CONVERSA ===\n' +
    historico.filter(m => m && m.role).map(m => {
      const role = m.role === 'assistant' ? 'Bia' : 'Cliente';
      return `${role}: ${m.conteudo || m.content || ''}`;
    }).join('\n') +
    '\n=== FIM DO HISTÓRICO ==='
  : '';

return [{
  json: {
    phone: cliente.phone,
    clienteId: cliente.clienteId,
    nomeCliente,
    userMessage: cliente.userMessage,
    stage,
    visitaAgendada: cliente.visitaAgendada,
    systemPrompt: systemPrompt + historicoFormatado,
    mensagensCompletas: [{ role: 'user', content: cliente.userMessage || 'Olá' }]
  }
}];

const dadosPrompt = $('Montar Prompt por Stage').item.json;
const gptData = $input.first().json;

let respostaCompleta = gptData?.message?.content
  || gptData?.choices?.[0]?.message?.content
  || 'Olá! Tudo bem? 😊';

const match = respostaCompleta.match(/\[AGENDAR:\s*([^\]]+)\]/i);
const agendar = !!match;
const dataVisitaTexto = match ? match[1].trim() : '';

const respostaGPT = respostaCompleta.replace(/\[AGENDAR:[^\]]+\]/gi, '').trim();

let novoStage = dadosPrompt.stage;
if (agendar) {
  novoStage = 'VISITA_AGENDADA';
} else if (dadosPrompt.stage === 'NOVO') {
  novoStage = 'ATENDIMENTO';
}

return [{
  json: {
    phone: dadosPrompt.phone,
    clienteId: dadosPrompt.clienteId,
    userMessage: dadosPrompt.userMessage,
    respostaGPT,
    stage: dadosPrompt.stage,
    novoStage,
    agendar,
    dataVisitaTexto
  }
}];

const resp = $('Extrair Resposta GPT').item.json;
const payload = [
  { cliente_id: resp.clienteId, role: 'user',      conteudo: resp.userMessage  || '' },
  { cliente_id: resp.clienteId, role: 'assistant', conteudo: resp.respostaGPT || '' }
];
return [{
  json: {
    bodyStr: JSON.stringify(payload),
    phone:           resp.phone,
    clienteId:       resp.clienteId,
    userMessage:     resp.userMessage,
    respostaGPT:     resp.respostaGPT,
    stage:           resp.stage,
    novoStage:       resp.novoStage,
    agendar:         resp.agendar,
    dataVisitaTexto: resp.dataVisitaTexto
  }
}];
